import type { BlogArticleFaq } from '../../../types/blog';

export const BODY: string = "\n<p>تحويل الصور واحدة تلو الأخرى مناسب لصورة واحدة. لمجلد فيه خمسون صورة، تحتاج إلى طريقة أسرع.</p>\n<p>العملية بسيطة: ارفع المجلد، واختر صيغة الإخراج، وثبّت الجودة مرة واحدة، وشغّل التحويل، ونزّل كل شيء كملف ZIP.</p>\n<p>يمر هذا الدليل بكل خطوة، مع الإعدادات التي تهم لدفعة نظيفة ومتسقة.</p>\n<h2 id=\"prepare-your-folder\">الخطوة 0: جهّز مجلدك أولًا</h2>\n<p>الخطوة 0: جهّز مجلدك أولًا. اجمع الصور التي تريد تحويلها في مجلد واحد، وتأكد من أنها الملفات الأصلية لا نسخ مضغوطة.</p>\n<p>أزل من المجلد أي ملفات لا تريد تحويلها. التنظيف المسبق يمنع تحويل ملفات غير مرغوبة بالخطأ.</p>\n<h2 id=\"upload-the-batch\">الخطوة 1: ارفع الدفعة كاملة</h2>\n<p>افتح <a href=\"/ar/tahwil-jumli-lis-suwar/\">محول الصور بالجملة</a> في متصفحك وارفع الدفعة كاملة. أسقط المجلد في منطقة الرفع أو اختر ملفاته.</p>\n<p>ستظهر كل صورة في قائمة مع صيغتها الأصلية. تحقق من أن كل الصور المطلوبة موجودة قبل المتابعة.</p>\n<h2 id=\"pick-the-target-format\">الخطوة 2: اختر صيغة الهدف</h2>\n<p>اختر صيغة الهدف حسب وجهة الصور: JPG للتوافق الكامل، وWebP لأصغر حجم على المواقع الحديثة، وPNG للنصوص والرسوم.</p>\n<p>إذا لم تكن متأكدًا، فاختر JPG. يعمل في كل مكان تقريبًا، وهو الخيار الآمن عندما لا تعرف متطلبات الوجهة.</p>\n<h2 id=\"set-quality-once\">الخطوة 3: ثبّت الجودة مرة واحدة</h2>\n<p>ثبّت الجودة مرة واحدة: جودة 85 مناسبة لمعظم الدفعات، و90 للجودة القصوى. الإعداد الواحد يطبق على كل الصور.</p>\n<p>للتحويل إلى PNG، لا يؤثر منزلق الجودة لأنه دون فقدان. أما JPG وWebP فيستخدمان الجودة لتحديد مقدار الضغط.</p>\n<h2 id=\"transparency-decisions\">الخطوة 4: قرر بشأن الشفافية</h2>\n<p>قرر بشأن الشفافية: إذا كانت بعض الصور شفافة واخترت JPG، فستفقد الشفافية. اختر PNG أو WebP للحفاظ عليها.</p>\n<p>إذا اخترت JPG، فاختر لون تعبئة يناسب خلفية موقعك. اللون الخاطئ يجعل الصور الشفافة تبدو غريبة.</p>\n<h2 id=\"convert-and-watch\">الخطوة 5: حوّل وراقب التقدم</h2>\n<p>حوّل وراقب التقدم: اضغط زر التحويل وتابع شريط التقدم. كل صورة تتحول على حدة، وتظهر النتائج تدريجيًا.</p>\n<p>الدفعة المتوسطة تستغرق دقائق معدودة. يمكنك متابعة التقدم وترك الأداة تعمل في الخلفية.</p>\n<h2 id=\"review-each-card\">الخطوة 6: راجع النتائج بطاقة بطاقة</h2>\n<p>راجع النتائج بطاقة بطاقة: افتح عينة من الصور المحوّلة وتأكد من جودتها وألوانها وشفافيتها إن وجدت.</p>\n<p>إذا بدت العينة جيدة، فالدفعة ناجحة. وإذا فشل ملف واحد، فأعد تحويله وحده بإعدادات مختلفة.</p>\n<h2 id=\"download-as-zip\">الخطوة 7: نزّل كل شيء كملف ZIP واحد</h2>\n<p>نزّل كل شيء كملف ZIP واحد: اضغط زر التنزيل واحفظ الملف في مجلد جديد منفصل عن الأصول.</p>\n<p>فك ضغط الملف وراجع النتائج قبل الاستخدام. التنظيم الجيد يمنع الخلط بين النسخ الأصلية والمحوّلة.</p>\n<ol>\n<li>ارفع الدفعة كاملة.</li>\n<li>اختر صيغة الهدف والجودة.</li>\n<li>حوّل وراقب التقدم.</li>\n<li>نزّل ملف ZIP.</li>\n</ol>\n<h2 id=\"fixing-failed-files\">كيف تصلح الملفات الفاشلة؟</h2>\n<p>لإصلاح الملفات الفاشلة، افحص سبب الفشل أولًا. الملف التالف أو الصيغة غير المدعومة هما السببان الأكثر شيوعًا.</p>\n<p>أعد تحويل الملف الفاشل وحده من الملف الأصلي. وإذا فشل مجددًا، فتحقق من فتحه في عارض صور. وللتحويل الفردي، استخدم <a href=\"/ar/tahwil-as-suwar/\">محول الصور</a>.</p>\n<h2 id=\"converting-again-to-another-format\">كيف تحوّل الدفعة نفسها إلى صيغة أخرى؟</h2>\n<p>لتحويل الدفعة نفسها إلى صيغة أخرى، أعد تشغيل الدفعة من الملفات الأصلية بصيغة إخراج مختلفة. لا تحوّل من النسخ المحوّلة.</p>\n<p>التحويل من الأصل يحافظ على الجودة. التحويل من نسخة محوّلة يضيف فقدان جودة في كل جولة.</p>\n<h2 id=\"mobile-batch-tips\">نصائح الدفعات للهواتف</h2>\n<p>نصائح الدفعات للهواتف: افتح المحول في المتصفح واختر عدة صور من معرضك. لكن الدفعات الكبيرة قد تستهلك ذاكرة الهاتف.</p>\n<p>قسّم الدفعات الكبيرة إلى مجموعات من 10 إلى 15 صورة على الهاتف. المجموعات الصغيرة أسرع وأقل عرضة للفشل.</p>\n<h2 id=\"keeping-originals-safe\">كيف تحافظ على ملفاتك الأصلية آمنة؟</h2>\n<p>للحفاظ على ملفاتك الأصلية آمنة، احفظ النتائج في مجلد جديد ولا تكتب فوق الأصول أبدًا. استخدم لاحقة اسم واضحة للنسخ المحوّلة.</p>\n<p>احتفظ بنسخة احتياطية من الأصول قبل أي دفعة كبيرة. الأصل لا يمكن استعادته إذا حُذف بعد التحويل.</p>\n<h2 id=\"sorting-before-upload\">كيف تفرز الملفات قبل الرفع؟</h2>\n<p>لفرز الملفات قبل الرفع، رتبها حسب النوع أو التاريخ في مجلدك. الفرز المسبق يسهّل مراجعة النتائج بعد التحويل.</p>\n<p>أزل الملفات المكررة قبل الرفع. التكرار يهدر وقت المعالجة ويضاعف حجم ملف ZIP.</p>\n<h2 id=\"converting-trip-photos\">كيف تحوّل صور رحلة؟</h2>\n<p>لتحويل صور رحلة، اجمعها في مجلد واحد وحوّلها إلى JPG بجودة متوازنة. الصور الموحدة أسهل في المشاركة والتخزين.</p>\n<p>سمِّ الملفات حسب المكان والتاريخ، مثل paris-2026-01.jpg. الأسماء الواضحة تجعل الألبوم أسهل في التصفح.</p>\n<h2 id=\"converting-work-documents\">كيف تحوّل مستندات العمل بالجملة؟</h2>\n<p>لتحويل مستندات العمل بالجملة، امسحها بوضوح ورتبها حسب التاريخ أو المشروع قبل الرفع. المستندات المنظمة أسهل في الاستخدام.</p>\n<p>استخدم PNG للمستندات النصية وJPG للصور الفوتوغرافية. الصيغة الصحيحة لكل نوع تعطي أفضل نتيجة.</p>\n<h2 id=\"reusing-settings\">كيف تعيد استخدام الإعدادات للدفعات المتكررة؟</h2>\n<p>لإعادة استخدام الإعدادات للدفعات المتكررة، سجّل إعداداتك الفائزة: الصيغة والجودة ولون التعبئة. السجل يختصر الإعداد في المرات القادمة.</p>\n<p>إذا كانت دفعاتك متشابهة، فاستخدم الإعدادات نفسها في كل مرة. الاتساق يجعل النتائج متوقعة وموثوقة.</p>\n<h2 id=\"converting-for-client-handover\">كيف تحوّل الصور لتسليمها إلى عميل؟</h2>\n<p>لتحويل الصور لتسليمها إلى عميل، استخدم إعدادات موحدة وسمِّ الملفات بوضوح. أرسل ملف ZIP واحدًا مع قائمة بالمحتويات.</p>\n<p>اذكر الصيغة والإعدادات المستخدمة في رسالة التسليم. وللتفاصيل الكاملة، اقرأ <a href=\"/ar/blog/dalil-tahwil-as-suwar-al-jumli/\">الدليل الكامل لمحول الصور بالجملة</a> و<a href=\"/ar/blog/sayr-amal-tahwil-as-suwar-al-jumli/\">سير عمل التحويل الجماعي</a>. وإذا كانت صورك بصيغة HEIC، فحوّلها أولًا باستخدام <a href=\"/ar/tahwil-heic-ila-jpg/\">محول HEIC إلى JPG</a>.</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"هل يمكنني سحب مجلد كامل إلى محول الجملة؟","answer":"نعم، اسحب المجلد كاملًا إلى منطقة الرفع أو اختره في نافذة الرفع. المتصفح يرفع كل الصور في المجلد معًا."},{"question":"ما أنواع الملفات التي يمكنني مزجها في دفعة واحدة؟","answer":"يمكنك مزج JPG وPNG وWebP وHEIC وBMP وGIF في دفعة واحدة. الأداة تتعرف على كل صيغة وتحوّلها إلى صيغة الإخراج المختارة."},{"question":"كيف أمنع الملفات المحوّلة من الكتابة فوق ملفاتي الأصلية؟","answer":"استخدم لاحقة اسم ملف واضحة، مثل sora-webp، واحفظ النتائج في مجلد جديد منفصل عن الأصول. بهذا لا تكتب النسخ المحوّلة فوق الأصول أبدًا."},{"question":"لماذا أصبح ملف في دفعتي أكبر بكثير بعد التحويل؟","answer":"لأن الصيغة الجديدة أكبر من الأصل: التحويل إلى PNG من JPG يكبّر الملف عدة مرات. تحقق من صيغة الإخراج، واستخدم JPG أو WebP للصور الفوتوغرافية."},{"question":"هل يمكنني إيقاف تحويل جماعي في منتصفه؟","answer":"لا، لا يمكن إيقاف الدفعة مؤقتًا. لكن يمكنك إلغاؤها والبدء مجددًا من الملفات الأصلية. لذلك راجع إعداداتك قبل البدء."},{"question":"هل يعمل محول الجملة دون اتصال بالإنترنت؟","answer":"نعم، التحويل يحدث بالكامل في متصفحك دون اتصال بالخادم. بعد تحميل الصفحة، يعمل كل شيء دون إنترنت."}];
